{
  "idea_id": "P07",
  "idea": "Low-cost interceptor components or software that reduce the military's cost per engagement.",
  "verdict": "kill",
  "tests": [
    {
      "id": "R001",
      "result": "fail",
      "evidence": "Manufacturing missile/interceptor hardware components (e.g., seekers, rocket motors, guidance) places these items on the USML under ITAR Category IV (guided missiles, rockets). ITAR registration/manufacturing licensing is mandatory regardless of company size ('ITAR does not have a small business exemption' per defensebizstack.ai guide), making the operator itself a licensed/regulated manufacturer of munitions, not merely a software vendor to a regulated customer.",
      "source_url": "https://defensebizstack.ai/guides/itar-compliance-for-manufacturers"
    },
    {
      "id": "T2",
      "result": "unknown",
      "evidence": "No single third-party platform dependency identified for this idea; not clearly applicable.",
      "source_url": null
    },
    {
      "id": "T3",
      "result": "fail",
      "evidence": "The idea explicitly includes 'interceptor components' -- physical hardware (e.g., seekers, motors, launchers) as sold by comparable companies like Perseus Defense ($2,500-$10K/unit hardware) and Martel Defense ($6K/shot kinetic interceptors). Building and delivering physical munitions components to the Army/primes requires manufacturing, storing, and shipping physical inventory (rocket motors, warheads, launchers) with no fully outsourced fulfillment path described or plausible at solo-founder scale without a dedicated facility.",
      "source_url": "https://www.perseusdefense.com/"
    },
    {
      "id": "T7",
      "result": "fail",
      "evidence": "Competitor evidence shows this space requires machine shops, fabrication equipment, electronics assembly, ISO 9001/CMMC/ITAR certified facilities, live-fire test ranges (e.g., Yuma Proving Ground), and teams of engineers -- e.g., Deployable Technologies charges $30K/month just for shared access to such infrastructure, explicitly citing $500K-$1M/year in engineering salaries alone plus facility/tooling costs as the baseline to avoid building this yourself. This is an obvious capital/physical infrastructure requirement beyond one person, even with AI agents.",
      "source_url": "https://deployabletechnologies.com/services/build/"
    }
  ],
  "flags": [
    {
      "id": "T4",
      "evidence": "Customer is 'US Army and defense primes' -- selling into DoD requires long procurement cycles, primes relationships, and often SBIR/OTA contracting vehicles, as seen with Perseus Defense briefing multiple Pentagon offices and running field tests with Fort Hood's 1st Cavalry Division before any contract."
    },
    {
      "id": "T6",
      "evidence": "Defense hardware sales cycles documented in search results (Perseus Defense, X-Bow Systems) show months-to-years from prototype to first paid engagement/contract, undermining a 90-day path to a paying customer for the hardware component of this idea."
    }
  ],
  "competitors": [
    {
      "name": "Perseus Defense",
      "url": "https://www.perseusdefense.com/",
      "relationship": "direct",
      "pricing": "~$2,500-$10,000 per interceptor",
      "evidence": "YC-backed startup building sub-$10K kinetic counter-drone interceptors explicitly to lower cost-per-kill for DoD/Army customers."
    },
    {
      "name": "Martel Defense",
      "url": "https://marteldefense.com/",
      "relationship": "direct",
      "pricing": "<$6,000 per shot",
      "evidence": "Two-tier kinetic interceptor system marketed explicitly on cost-exchange-ratio economics versus expensive fielded interceptors."
    },
    {
      "name": "X-Bow Systems",
      "url": "https://defensescoop.com/2026/08/19/mda-contract-award-x-bow-low-cost-interceptor/",
      "relationship": "direct",
      "pricing": "Contract-based, MDA Low-Cost Interceptor program (<$750K/missile target)",
      "evidence": "Awarded MDA contract to build low-cost interceptor components (solid rocket motors) as part of the Army's decomposed interceptor supply chain."
    },
    {
      "name": "Deployable Technologies Inc.",
      "url": "https://deployabletechnologies.com/services/build/",
      "relationship": "adjacent",
      "pricing": "$30,000/month subscription",
      "evidence": "Manufacturing-as-a-Service provider explicitly built to let defense innovators avoid the $500K-$1M/year and multi-year ITAR/CMMC facility buildout normally required to produce hardware like this."
    }
  ],
  "queries": {
    "exa": [
      "low-cost interceptor startup defense company cost per kill",
      "solo founder defense hardware startup selling to US Army primes",
      "one person company build defense hardware components without facility"
    ],
    "brave": [
      "low-cost interceptor components company defense primes",
      "\"cost per kill\" interceptor startup funding defense",
      "ITAR license required manufacture missile components small business"
    ]
  },
  "proposed_variant": {
    "idea": "Software-only fire-control, targeting, or cost-optimization algorithms sold as a licensed product/SaaS to existing interceptor manufacturers and defense primes, with no physical component manufacturing, inventory, or munitions handling by the operator.",
    "reason": "Removing the physical 'components' (munitions/hardware) half of the idea and ITAR-controlled article production eliminates the manufacturing/inventory/facility requirements (T3, T7) and the ITAR manufacturer-licensing exposure (R001), leaving a pure software sale to a regulated customer, which is explicitly permitted under R001's carve-out."
  },
  "injection_seen": []
}
